  "Aynı oyuncular her hafta birlikte çalıştıkça kimya gelişir. Yeni bir transferin mevcut oyuncularla uyumu zamanla artar.": [
    "Chemistry improves as the same players train together each week. New signings gradually build chemistry with the squad.",
    "Die Chemie steigt, wenn dieselben Spieler jede Woche zusammen trainieren. Neuzugänge gewöhnen sich mit der Zeit an den Kader.",
    "La cohésion progresse quand les mêmes joueurs s’entraînent chaque semaine. Les recrues s’intègrent au fil du temps.",
    "L’intesa migliora quando gli stessi giocatori si allenano insieme ogni settimana. I nuovi acquisti si integrano col tempo.",
    "La química mejora cuando los mismos jugadores entrenan juntos cada semana. Los fichajes se adaptan al equipo con el tiempo.",
    "O entrosamento melhora quando os mesmos jogadores treinam juntos a cada semana. Novas contratações se adaptam ao elenco com o tempo.",
    "Сыгранность растёт, когда игроки тренируются вместе каждую неделю. Новички постепенно налаживают связи с составом.",
    "同じ選手が毎週一緒に練習すると連携が向上します。新加入選手も時間をかけてチームになじみます。",
    "Η χημεία βελτιώνεται όταν οι ίδιοι παίκτες προπονούνται μαζί κάθε εβδομάδα. Οι νέες μεταγραφές προσαρμόζονται σταδιακά.",
    "相同选手每周共同训练会提升默契，新援也会逐渐融入阵容。",
    "相同選手每週共同訓練會提升默契，新援也會逐漸融入陣容。"
  ],
