  "İlk 5'ten satış yapınca yedek oyuncu otomatik olarak kadroya geçer. Yedekleri ise ilk 5'i bozmadan satabilirsin.": [
    "Selling a starter automatically promotes a substitute into the lineup. Substitutes can be sold without changing the starting five.",
    "Beim Verkauf eines Stammspielers rückt automatisch ein Ersatzspieler nach. Ersatzspieler kannst du ohne Änderung der Startaufstellung verkaufen.",
    "Vendre un titulaire fait automatiquement monter un remplaçant. Vendre un remplaçant ne change pas les cinq titulaires.",
    "Vendere un titolare promuove automaticamente una riserva. Puoi vendere le riserve senza modificare i cinque titolari.",
    "Vender un titular incorpora automáticamente a un suplente. Puedes vender suplentes sin cambiar el quinteto titular.",
    "Vender um titular promove automaticamente um reserva. Você pode vender reservas sem mudar o quinteto titular.",
    "Продажа игрока основы автоматически вводит запасного. Запасных можно продать без изменения основной пятёрки.",
    "先発を売却すると控えが自動的に先発に入ります。控えは先発5人を変えずに売却できます。",
    "Η πώληση βασικού προωθεί αυτόματα αναπληρωματικό. Μπορείς να πουλήσεις αναπληρωματικούς χωρίς αλλαγή πεντάδας.",
    "出售首发后会自动由替补补位，出售替补则不会改变首发五人。",
    "出售先發後會自動由替補補位，出售替補則不會改變先發五人。"
  ],
  "Oyuncuların seviyeleri bulunduğun lige göre belirlenir. Bir oyuncu seçip önce kulüple, sonra oyuncuyla şartları görüş.": [
    "Player levels depend on your league. Select a player and negotiate with their club first, then with the player.",
    "Spielerstärken richten sich nach deiner Liga. Wähle einen Spieler und verhandle zuerst mit dem Club, dann mit dem Spieler.",
    "Le niveau des joueurs dépend de ta ligue. Choisis un joueur, négocie avec le club puis avec lui.",
    "Il livello dei giocatori dipende dal tuo campionato. Scegli un giocatore e tratta prima col club, poi con lui.",
    "El nivel de los jugadores depende de tu liga. Elige un jugador y negocia primero con el club y luego con él.",
    "O nível dos jogadores depende da sua liga. Escolha um jogador e negocie com o clube primeiro, depois com ele.",
    "Уровень игроков зависит от вашей лиги. Выберите игрока и обсудите условия сначала с клубом, затем с ним.",
    "市場の選手レベルは所属リーグに応じて決まります。選手を選び、まずクラブ、次に選手本人と条件を交渉しましょう。",
    "Το επίπεδο παικτών εξαρτάται από τη λίγκα σου. Διάλεξε παίκτη και συζήτησε όρους πρώτα με τον σύλλογο, μετά με τον ίδιο.",
    "选手水平由所处联赛决定。选择选手后，先与俱乐部、再与选手本人谈条件。",
    "選手水平由所處聯賽決定。選擇選手後，先與俱樂部、再與選手本人談條件。"
  ],
  "{0} oyuncu · En yüksek GEN üstte. Rol seçimi oyuncunun özelliklerini veya mevcut rolünü değiştirmez; bütün adayları seçtiğin rolde değerlendirir.": [
    "{0} players · Highest OVR first. Choosing a role evaluates every candidate in that role without changing their attributes or current role.",
    "{0} Spieler · Höchster GES zuerst. Die Rollenwahl bewertet alle Kandidaten in dieser Rolle, ohne Attribute oder aktuelle Rollen zu ändern.",
    "{0} joueurs · GEN décroissant. Le rôle choisi évalue chaque candidat sans changer ses attributs ni son rôle actuel.",
    "{0} giocatori · GEN più alto prima. Scegliere un ruolo valuta tutti in quel ruolo senza cambiare attributi o ruolo attuale.",
    "{0} jugadores · Mayor GRL primero. El rol elegido evalúa a todos en ese rol sin cambiar sus atributos ni su rol actual.",
    "{0} jogadores · Maior GER primeiro. A função escolhida avalia todos nela sem alterar atributos ou função atual.",
    "{0} игроков · Сначала высокий ОБЩ. Выбранная роль оценивает всех в ней, не меняя навыки и текущие роли.",
    "{0}人・総合の高い順。選んだ役割で全候補を評価し、能力や現在の役割は変えません。",
    "{0} παίκτες · Υψηλότερο ΣΥΝ πρώτα. Ο ρόλος αξιολογεί όλους σε αυτόν χωρίς αλλαγή χαρακτηριστικών ή τρέχοντος ρόλου.",
    "{0}名选手 · 总评从高到低。选定角色会以该角色评估所有候选人，不改变属性或当前角色。",
    "{0}名選手 · 總評由高至低。選定角色會以該角色評估所有候選人，不改變屬性或目前角色。"
  ],
