  "İlk 5 ve yedeklere uygulanır. Akademi ve harita antrenmanı ayrı çalışır. Plan, Haftayı Bitir dediğinde gelişim ve toparlanmaya birlikte uygulanır.": [
    "Applies to starters and substitutes. Academy and map training are separate. Ending the week applies this plan to development and recovery together.",
    "Gilt für Stamm- und Ersatzspieler. Akademie- und Kartentraining sind getrennt. Beim Wochenabschluss wirkt der Plan auf Entwicklung und Erholung.",
    "S’applique aux titulaires et remplaçants. Académie et cartes sont séparées. Le plan agit sur progression et récupération en terminant la semaine.",
    "Vale per titolari e riserve. Accademia e mappe sono separate. A fine settimana il piano si applica a crescita e recupero insieme.",
    "Afecta a titulares y suplentes. Academia y mapas van aparte. Al terminar la semana se aplica al desarrollo y recuperación.",
    "Vale para titulares e reservas. Academia e mapas são separados. Ao encerrar a semana, o plano afeta evolução e recuperação.",
    "Действует на основу и запас. Академия и карты тренируются отдельно. При завершении недели план влияет на развитие и восстановление.",
    "先発と控えに適用され、アカデミーとマップ練習は別です。週を終える際に成長と回復に反映されます。",
    "Ισχύει για βασικούς και πάγκο. Ακαδημία και χάρτες είναι ξεχωριστά. Στο τέλος εβδομάδας το πλάνο επηρεάζει ανάπτυξη και αποκατάσταση.",
    "适用于首发与替补，青训和地图训练独立。结束本周时同时作用于成长和恢复。",
    "適用於先發與替補，青訓和地圖訓練獨立。結束本週時同時作用於成長和恢復。"
  ],
  "Yoğun çalışma sürekli en iyi seçenek değildir. Yorgunluk maç performansını ve yoğun antrenman verimini etkiler. Yaşa bağlı gerileme ve potansiyel sınırı değişmez.": [
    "Intensive training is not always best. Fatigue affects match performance and training efficiency. Age-related decline and potential limits still apply.",
    "Intensiv ist nicht immer am besten. Müdigkeit beeinflusst Spielleistung und Trainingseffizienz. Altersrückgang und Potenzialgrenzen bleiben bestehen.",
    "L’intensif n’est pas toujours idéal. La fatigue affecte performance et efficacité de l’entraînement. Déclin lié à l’âge et potentiel restent inchangés.",
    "L’intenso non è sempre ideale. La fatica influisce su prestazioni ed efficienza. Declino per età e limite di potenziale restano validi.",
    "El intenso no siempre es mejor. La fatiga afecta rendimiento y eficiencia del entrenamiento. El declive por edad y el límite de potencial siguen vigentes.",
    "Treino intenso nem sempre é melhor. A fadiga afeta desempenho e eficiência. Declínio por idade e limite de potencial continuam valendo.",
    "Интенсивность не всегда оптимальна. Усталость влияет на матч и эффективность тренировок. Возрастной спад и предел потенциала сохраняются.",
    "集中的な練習が常に最適とは限りません。疲労は試合と練習効率に影響し、年齢の衰えや潜在能力上限は変わりません。",
    "Η εντατική προπόνηση δεν είναι πάντα καλύτερη. Η κόπωση επηρεάζει αγώνα και απόδοση προπόνησης. Η ηλικιακή πτώση και το όριο δυναμικού παραμένουν.",
    "高强度并非总是最佳选择。疲劳影响比赛表现及训练效率，年龄衰退与潜力上限仍有效。",
    "高強度並非總是最佳選擇。疲勞影響比賽表現及訓練效率，年齡衰退與潛力上限仍有效。"
  ],
