    "A academia tem 2 / 4 / 6 vagas conforme o olheiro. Cada missão traz 1–2 candidatos.",
    "В академии 2 / 4 / 6 мест по уровню скаута. Каждое задание даёт 1–2 кандидата.",
    "スカウトレベルに応じ定員は2 / 4 / 6人。1回の任務で1〜2人の候補が来ます。",
    "Η ακαδημία χωρά 2 / 4 / 6 παίκτες ανά επίπεδο σκάουτερ. Κάθε αποστολή φέρνει 1–2 υποψηφίους.",
    "青训容量依球探等级为2 / 4 / 6人，每次考察带回1–2名候选人。",
