  "Piyasada oyuncu detayından takip ekle. Piyasadan ayrılan oyuncunun son bilinen bilgileri korunur. Kadrona kattığında aynı oyuncuyu takip etmeye devam edersin.": [
    "Follow players from market profiles. Last-known details stay after they leave the market. Tracking continues if you sign them.",
    "Beobachte Spieler über Marktprofile. Letzte Daten bleiben nach Marktaustritt erhalten. Nach Verpflichtung läuft die Beobachtung weiter.",
    "Suis les joueurs depuis leurs profils sur le marché. Les dernières données restent après leur départ. Le suivi continue si tu les recrutes.",
    "Segui i giocatori dai profili di mercato. Gli ultimi dati restano dopo l’uscita dal mercato. L’osservazione continua dopo l’ingaggio.",
    "Sigue jugadores desde sus perfiles del mercado. Se conservan los últimos datos al salir del mercado. El seguimiento continúa si los fichas.",
    "Observe jogadores pelos perfis do mercado. Os últimos dados ficam após saírem do mercado. A observação continua após contratá-los.",
    "Следите из рыночных профилей. Последние данные сохраняются после ухода с рынка. Наблюдение продолжается и после перехода к вам.",
    "市場のプロフィールから追跡できます。市場を離れても最終情報が残り、獲得後も追跡は続きます。",
    "Παρακολούθησε από προφίλ αγοράς. Τα τελευταία δεδομένα μένουν όταν φύγουν από αυτήν. Η παρακολούθηση συνεχίζεται μετά την απόκτησή τους.",
    "可从市场选手详情关注，离开市场后保留最后信息，签入本队后也继续关注。",
    "可從市場選手詳情關注，離開市場後保留最後資訊，簽入本隊後也繼續關注。"
  ],
