  "Yenileme: +26 hafta. Ücret 4 haftalık maaş; ücret ve yeni maaş güncel piyasa değerine göre sınırlandırılır. Maaş artışı en fazla %15, yeni maaş piyasa maaşının en fazla %20 üstüdür.": [
    "Renewal adds 26 weeks and costs 4 weeks’ wages. Fees and new wages are capped by current market value. Wage increases are at most 15%, with new wages at most 20% above market wages.",
    "Verlängerung um 26 Wochen, Gebühr 4 Wochengehälter. Gebühr und neues Gehalt sind nach Marktwert begrenzt. Gehaltsanstieg höchstens 15 %, neues Gehalt höchstens 20 % über Marktgehalt.",
    "Renouvellement : +26 semaines, coût de 4 salaires hebdomadaires. Frais et nouveau salaire sont plafonnés selon le marché. Hausse maximale de 15 %, nouveau salaire au plus 20 % au-dessus du marché.",
    "Rinnovo: +26 settimane, costo di 4 stipendi settimanali. Costo e nuovo stipendio sono limitati dal mercato. Aumento massimo 15%, nuovo stipendio massimo 20% sopra quello di mercato.",
    "Renovación: +26 semanas y coste de 4 salarios semanales. Coste y nuevo salario se limitan según el mercado. Subida máxima del 15%, nuevo salario como máximo un 20% sobre el de mercado.",
    "Renovação: +26 semanas, custo de 4 salários semanais. Custo e novo salário são limitados pelo mercado. Aumento máximo de 15%, novo salário no máximo 20% acima do mercado.",
    "Продление: +26 недель за 4 недельных зарплаты. Плата и новая зарплата ограничены рынком. Повышение не более 15 %, новая зарплата не более чем на 20 % выше рыночной.",
    "更新は26週追加で費用は週給4週分。費用と新給与は市場価値により制限されます。昇給は最大15%、新給与は市場給与の最大20%上までです。",
    "Ανανέωση: +26 εβδομάδες με κόστος 4 εβδομαδιαίων μισθών. Κόστος και νέος μισθός περιορίζονται από την αγορά. Αύξηση έως 15%, νέος μισθός έως 20% πάνω από την αγορά.",
    "续约增加26周，费用为4周工资；费用与新工资受当前市场价值限制。涨薪最多15%，新工资最多高于市场工资20%。",
    "續約增加26週，費用為4週薪資；費用與新薪資受目前市場價值限制。調薪最多15%，新薪資最多高於市場薪資20%。"
  ],
  "Sözleşmesi biten oyuncu {0} hafta içinde yenilenmezse ayrılır. Morali 40'ın altındaki oyuncu yenilemeyi reddeder.": [
    "An out-of-contract player leaves unless renewed within {0} weeks. Players below 40 morale refuse renewals.",
    "Vertragslose Spieler gehen ohne Verlängerung innerhalb von {0} Wochen. Unter 40 Moral lehnen sie Verlängerungen ab.",
    "Un joueur sans contrat part si non renouvelé sous {0} semaines. Sous 40 de moral, il refuse de renouveler.",
    "Chi è senza contratto parte senza rinnovo entro {0} settimane. Sotto 40 di morale rifiuta il rinnovo.",
    "Un jugador sin contrato se va si no renuevas en {0} semanas. Con moral inferior a 40 rechaza renovar.",
    "Jogador sem contrato sai se não renovar em {0} semanas. Moral abaixo de 40 faz recusar a renovação.",
    "Игрок с истёкшим контрактом уйдёт без продления за {0} недель. При морали ниже 40 откажется продлевать.",
    "契約切れから{0}週以内に更新しないと退団します。士気40未満の選手は更新を拒否します。",
    "Παίκτης χωρίς συμβόλαιο φεύγει αν δεν ανανεωθεί σε {0} εβδομάδες. Με ηθικό κάτω από 40 αρνείται ανανέωση.",
    "合同到期后{0}周内不续约则离队，士气低于40的选手会拒绝续约。",
    "合約到期後{0}週內不續約則離隊，士氣低於40的選手會拒絕續約。"
  ],
