    "Antes dos prêmios, preserve o orçamento da escolha e fique sem dívidas.",
    "До призов сохраните бюджет на момент выбора цели и не имейте долгов.",
    "シーズン報酬前に、目標選択時の予算を維持し借金をなくす。",
