    "Dopo la scelta, promuovi almeno un giovane in panchina.",
    "Tras elegirlo, asciende al menos un canterano al banquillo.",
    "Após escolher, promova ao menos um jovem da academia ao banco.",
    "После выбора повысьте хотя бы одного воспитанника в запас.",
    "目標選択後、アカデミーから1人以上を控えに昇格させる。",
    "Μετά την επιλογή προώθησε τουλάχιστον έναν νέο στον πάγκο.",
    "选定目标后，至少提拔一名青训选手至替补阵容。",
