    "Melhore pelo menos 2 GER de um jogador com menos de 24 na escolha e mantenha-o até o fim.",
    "Улучшите минимум на 2 ОБЩ игрока младше 24 при выборе и сохраните его до конца сезона.",
    "選択時に24歳未満の選手を総合2以上育て、シーズン末まで在籍させる。",
