  "Rakip ikinci yarıda taktik değiştirebilir. Aşağıdaki değerler rakibin ilk yarı taktiğine göre hesaplandı. Analist seviye 3 rakibin ikinci yarı taktiğini önceden gösterir.": [
    "The opponent may change tactics in the second half. The values below use their first-half tactic. A level 3 analyst reveals their second-half tactic in advance.",
    "Der Gegner kann in der zweiten Hälfte die Taktik ändern. Die Werte unten basieren auf seiner Taktik der ersten Hälfte. Ein Analyst auf Stufe 3 zeigt die Taktik der zweiten Hälfte im Voraus.",
    "L’adversaire peut changer de tactique en seconde période. Les valeurs ci-dessous utilisent sa tactique de première période. Un analyste de niveau 3 révèle à l’avance sa tactique de seconde période.",
    "L’avversario può cambiare tattica nel secondo tempo. I valori sotto si basano sulla sua tattica del primo tempo. Un analista di livello 3 rivela in anticipo la tattica del secondo tempo.",
    "El rival puede cambiar de táctica en la segunda mitad. Los valores siguientes usan su táctica de la primera mitad. Un analista de nivel 3 revela su táctica para la segunda mitad.",
    "O adversário pode mudar de tática no segundo tempo. Os valores abaixo usam a tática do primeiro tempo. Um analista de nível 3 revela a tática do segundo tempo antecipadamente.",
    "Во второй половине соперник может сменить тактику. Значения ниже рассчитаны по его тактике первой половины. Аналитик уровня 3 заранее показывает тактику второй половины.",
    "相手は後半に戦術を変更することがあります。以下の数値は前半の相手戦術で計算されています。レベル3のアナリストは相手の後半戦術を事前に明かします。",
    "Ο αντίπαλος μπορεί να αλλάξει τακτική στο δεύτερο ημίχρονο. Οι τιμές παρακάτω βασίζονται στην τακτική του πρώτου ημιχρόνου. Αναλυτής επιπέδου 3 αποκαλύπτει εκ των προτέρων την τακτική του δεύτερου ημιχρόνου.",
    "对手可能在下半场更换战术。以下数值按其上半场战术计算。3级分析师可提前揭示对手下半场的战术。",
    "對手可能在下半場更換戰術。以下數值按其上半場戰術計算。3級分析師可提前揭示對手下半場的戰術。"
  ],
