    "Διάλεξε τακτική πρώτου ημιχρόνου. Επειδή δεν γνωρίζεις την τακτική του αντιπάλου, βλέπεις μόνο τη συμβατότητα του ρόστερ.",
    "选择上半场战术。由于对手战术未知，只显示阵容适配。",
