    "他クラブから選手へのオファーが届いています。オファーは次のシーズン終了まで有効です。",
    "Άλλοι σύλλογοι έκαναν προσφορές για τους παίκτες σου. Ισχύουν έως το τέλος της επόμενης σεζόν.",
    "其他俱乐部向你的选手提出报价，有效期至下赛季结束。",
