  "Adaylar yalnızca tamamlanan keşif görevlerinden gelir. Scout seviyesi yükseldikçe güçlü yetenek bulma şansı artar ve potansiyel tahmini daralır.": [
    "Candidates arrive only from completed scouting missions. Higher scout levels increase the chance of finding strong talent and narrow the potential estimate.",
    "Kandidaten erscheinen nur nach abgeschlossenen Scout-Aufträgen. Höhere Scout-Stufen steigern die Chance auf starke Talente und präzisieren die Potenzialschätzung.",
    "Les candidats arrivent uniquement après une mission terminée. Un recruteur de niveau supérieur trouve plus souvent de grands talents et estime plus précisément leur potentiel.",
    "I candidati arrivano solo da missioni completate. Scout di livello superiore trovano più spesso grandi talenti e stimano il potenziale con più precisione.",
    "Los candidatos solo llegan de misiones completadas. Un ojeador de mayor nivel encuentra más talentos fuertes y estima su potencial con mayor precisión.",
    "Candidatos chegam apenas de missões concluídas. Olheiros de nível maior encontram mais talentos fortes e estimam o potencial com mais precisão.",
    "Кандидаты появляются только после завершённых заданий. С ростом уровня скаута растёт шанс найти сильный талант и сужается диапазон оценки потенциала.",
    "候補選手は完了したスカウト任務からのみ登場します。レベルが高いほど有望選手の発見率が上がり、推定ポテンシャルの幅が狭まります。",
    "Οι υποψήφιοι προέρχονται μόνο από ολοκληρωμένες αποστολές. Υψηλότερο επίπεδο σκάουτερ αυξάνει την πιθανότητα δυνατών ταλέντων και βελτιώνει την εκτίμηση δυναμικού.",
    "候选人仅来自已完成的球探任务。球探等级越高，发现强力新秀的概率越大，潜力估值范围也越精确。",
    "候選人僅來自已完成的球探任務。球探等級越高，發現強力新秀的機率越大，潛力估值範圍也越精確。"
  ],
