    ". Выбор стратегии сохраняет этих пятерых и меняет только роли. Чтобы задействовать запасных, используйте кнопку стартовой пятёрки ниже.",
    "。戦略選択ではこの5人を維持し、役割のみを調整します。控え選手を含めるには下の先発5人ボタンを使ってください。",
    ". Η επιλογή στρατηγικής κρατά αυτούς τους πέντε και αλλάζει μόνο τους ρόλους. Χρησιμοποίησε το κουμπί Αρχική πεντάδα παρακάτω για να συμπεριλάβεις αναπληρωματικούς.",
    "。选择战略会保留这五位选手，仅调整位置。若要启用替补，请使用下方首发五人按钮。",
    "。選擇戰略會保留這五位選手，僅調整位置。若要啟用替補，請使用下方先發五人按鈕。"
