  "Transfer imza parası": ["Transfer signing bonus","Handgeld für Transfers","Prime à la signature du transfert","Premio alla firma del trasferimento","Prima de fichaje","Prémio de assinatura da transferência","Подписной бонус за трансфер","移籍契約金","Μπόνους υπογραφής μεταγραφής","转会签字费","轉會簽約金"],
  "Sponsor fesih cezası": ["Sponsor termination fee","Gebühr für die Kündigung des Sponsorvertrags","Indemnité de résiliation du contrat de sponsoring","Penale per la risoluzione della sponsorizzazione","Penalización por rescindir el patrocinio","Penalização por rescisão do patrocínio","Штраф за расторжение спонсорского договора","スポンサー契約解除料","Ρήτρα λύσης χορηγίας","赞助解约费用","贊助解約費用"],
  "Başlayan play-off serisini tamamlamalısın.": ["You must finish the playoff series once it has started.","Du musst die begonnene Play-off-Serie beenden.","Vous devez terminer la série de barrage commencée.","Devi completare la serie playoff già iniziata.","Debes terminar la serie de promoción una vez iniciada.","Tens de terminar a série de play-off depois de a iniciares.","Необходимо завершить начатую серию плей-офф.","開始した入れ替え戦のシリーズを最後までプレイしてください。","Πρέπει να ολοκληρώσεις τη σειρά μπαράζ αφού ξεκινήσει.","附加赛系列开始后必须完成。","附加賽系列開始後必須完成。"],
  "Reklam gizlilik tercihleri": ["Ad privacy settings","Datenschutzeinstellungen für Werbung","Préférences de confidentialité des annonces","Preferenze sulla privacy degli annunci","Preferencias de privacidad de anuncios","Preferências de privacidade de anúncios","Настройки конфиденциальности рекламы","広告のプライバシー設定","Προτιμήσεις απορρήτου διαφημίσεων","广告隐私设置","廣告隱私設定"],
